import Foundation

var span = Measurement(value: 3, unit: UnitLength.kilometers)
let gap  = Measurement(value: 500, unit: UnitLength.meters)
let total = span + gap                    // 3500.0 m (converted to the base unit)
total.converted(to: .feet)                // 11482.94 ft

extension UnitLength {                    // Fowler's Conversion Ratio, declared once
    static let league = UnitLength(symbol: "lg",
                                   converter: UnitConverterLinear(coefficient: 5556))
}

