import Foundation

var span = Measurement(value: 3, unit: UnitLength.kilometers)
let gap  = Measurement(value: 500, unit: UnitLength.meters)
let total = span + gap                    // 3500.0 m (converted to the base unit)
total.converted(to: .feet)                // 11482.94 ft

extension UnitLength {                    // Fowler's Conversion Ratio, declared once
    static let league = UnitLength(symbol: "lg",
                                   converter: UnitConverterLinear(coefficient: 5556))
}

struct Length: Equatable {
    private let metres: Double                       // canonical stored unit
    private init(metres: Double) { self.metres = metres }
    static func kilometers(_ km: Double) -> Length { Length(metres: km * 1000) }
    static func meters(_ m: Double) -> Length { Length(metres: m) }
    var inFeet: Double { metres * 3.280839895 }
    static func + (a: Length, b: Length) -> Length { Length(metres: a.metres + b.metres) }
}
